<template><main class="admin-content"><NuxtLink to="/admin/accounting" class="text-sm font-bold text-blue-600">← Accounting</NuxtLink><h1 class="mt-2 text-3xl font-black">Suppliers & Purchases</h1><p class="text-slate-500">Supplier catalogue assignments, purchase orders, bills and Accounts Payable.</p><div v-if="msg" class="my-4 rounded-lg bg-slate-100 p-3">{{msg}}</div>

<div class="mt-5 grid gap-5 xl:grid-cols-2"><section class="panel p-5"><h2 class="text-xl font-black">Suppliers</h2><div class="mt-3 grid grid-cols-2 gap-2"><input v-model="supplier.name" class="input" placeholder="Supplier name"><input v-model="supplier.contact_name" class="input" placeholder="Contact"><input v-model="supplier.email" class="input" placeholder="Email"><input v-model="supplier.phone" class="input" placeholder="Phone"><input v-model="supplier.abn" class="input" placeholder="ABN"><button class="primary" @click="addSupplier">Add Supplier</button></div><div class="mt-4 divide-y"><div v-for="s in suppliers" :key="s.id" class="py-2"><b>{{s.name}}</b><span class="ml-2 text-xs text-slate-500">{{s.email}}</span></div></div></section>

<section class="panel p-5"><h2 class="text-xl font-black">Assign Supplier to Product</h2><p class="mt-1 text-sm text-slate-500">A product can have multiple suppliers, including a preferred primary supplier.</p><select v-model.number="mapping.product_id" class="input mt-3"><option :value="0">Choose store product…</option><option v-for="x in products" :value="x.id">{{x.name}} · {{x.product_code||'No product code'}}</option></select><select v-model.number="mapping.supplier_id" class="input mt-2"><option :value="0">Choose supplier…</option><option v-for="s in suppliers" :value="s.id">{{s.name}}</option></select><div class="mt-2 grid grid-cols-2 gap-2"><input v-model="mapping.supplier_sku" class="input" placeholder="Supplier SKU / code"><input v-model.number="mapping.buy_price_ex_gst" type="number" step=".01" class="input" placeholder="Buy price ex GST"></div><input v-model="mapping.supplier_product_name" class="input mt-2" placeholder="Supplier's product name (optional)"><label class="mt-3 flex items-center gap-2 text-sm font-bold"><input v-model="mapping.is_primary" type="checkbox"> Primary supplier for this product</label><button class="primary mt-3" @click="assignSupplier">Save Product Supplier</button><div class="mt-4 max-h-56 overflow-auto divide-y"><div v-for="m in mappings" :key="m.id" class="py-2 text-sm"><b>{{m.products?.name}}</b> → {{m.accounting_suppliers?.name}} <span v-if="m.is_primary" class="badge">Primary</span><div class="text-xs text-slate-500">{{m.supplier_sku||'No supplier SKU'}} · {{m.buy_price_ex_gst==null?'Store buy price':money(m.buy_price_ex_gst)+' ex GST'}}</div></div></div></section></div>

<section class="panel mt-5 p-5"><h2 class="text-xl font-black">{{ editingPoId ? `Edit Purchase Order — ${editingPoNumber}` : "New Purchase Order" }}</h2><p v-if="editingPoId" class="mt-1 text-sm text-amber-700">Draft purchase order — changes can be made until it is sent to the supplier.</p><div class="mt-3 grid gap-3 md:grid-cols-3"><select v-model.number="po.supplier_id" class="input" @change="supplierChanged"><option :value="0">Choose supplier…</option><option v-for="s in suppliers" :value="s.id">{{s.name}}</option></select><input v-model="po.expected_date" type="date" class="input"><input v-model="po.supplier_reference" class="input" placeholder="Supplier reference"></div><div v-if="po.supplier_id" class="mt-4 rounded-xl bg-blue-50 p-4"><b>Add Store Product</b><p class="text-xs text-slate-500">Shows products assigned to {{supplierName(po.supplier_id)}}.</p><div class="mt-2 flex gap-2"><select v-model.number="selectedMapping" class="input"><option :value="0">Choose assigned product…</option><option v-for="m in supplierProducts" :value="m.id">{{m.product?.name}} · {{m.supplier_sku||m.product?.product_code||'No product code'}}</option></select><button class="primary shrink-0" @click="addMappedProduct">+ Add</button></div></div><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[800px] text-sm"><thead><tr class="border-b text-left"><th class="p-2">SKU</th><th>Product / Description</th><th class="w-24">Qty</th><th class="w-40">Buy Price ex GST</th><th class="text-right">Line ex GST</th><th></th></tr></thead><tbody><tr v-for="(l,n) in po.lines" :key="n" class="border-b"><td class="p-2"><input v-model="l.sku" class="input"></td><td><input v-model="l.description" class="input"></td><td><input v-model.number="l.quantity" class="input" type="number" min="1"></td><td><input v-model.number="l.unit_cost_ex_gst" class="input" type="number" step=".01"></td><td class="text-right font-bold">{{money(Number(l.quantity)*Number(l.unit_cost_ex_gst))}}</td><td><button class="text-red-600" @click="po.lines.splice(n,1)">Remove</button></td></tr></tbody></table></div><div class="mt-3 flex flex-wrap justify-between gap-3"><button class="secondary" @click="po.lines.push(line())">+ Custom Line</button><div class="text-right text-sm"><div>Subtotal {{money(poSubtotal)}}</div><div>GST {{money(poSubtotal*.1)}}</div><div class="text-lg font-black">Total {{money(poSubtotal*1.1)}}</div></div><div class="flex gap-2"><button v-if="editingPoId" class="secondary" @click="cancelEdit">Cancel Edit</button><button class="primary" @click="savePO">{{ editingPoId ? "Save Changes" : "Create Purchase Order" }}</button></div></div></section>

<section class="panel mt-5 p-5"><h2 class="text-xl font-black">Purchase Orders</h2><div class="mt-3 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">PO</th><th>Supplier</th><th>Date</th><th>Status</th><th class="text-right">GST</th><th class="text-right">Total</th><th></th></tr></thead><tbody><tr v-for="x in pos" class="border-b"><td class="p-2 font-bold">{{x.po_number}}</td><td>{{x.accounting_suppliers?.name}}</td><td>{{x.order_date}}</td><td>{{x.status}}</td><td class="text-right">{{money(x.gst_amount)}}</td><td class="text-right">{{money(x.total)}}</td><td class="text-right"><div class="flex flex-wrap justify-end gap-2"><button v-if="isDraft(x)" class="secondary" @click="editPO(x)">Edit PO</button><button v-if="isDraft(x)" class="primary" @click="sendPO(x)">Send to Supplier</button><button v-if="isDraft(x)" class="secondary" @click="markOrdered(x)">Mark as Ordered</button><button v-if="isDraft(x)" class="text-red-600 rounded-lg border border-red-200 bg-red-50 px-4 py-2 text-sm font-bold" @click="closePO(x)">Close Order</button><button v-if="canReceive(x) && hasReceivable(x)" class="secondary" @click="openReceive(x)">Receive Stock</button><button v-if="canBill(x)" class="secondary" @click="convertToBill(x)">Convert to Bill</button><span v-if="x.status==='billed'" class="badge">Billed</span></div></td></tr></tbody></table></div></section>

<section class="panel mt-5 p-5"><h2 class="text-xl font-black">Supplier Bills / Accounts Payable</h2><div class="mt-3 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">Bill</th><th>Supplier</th><th>Supplier Invoice</th><th>Status</th><th class="text-right">Total</th><th class="text-right">Owing</th><th></th></tr></thead><tbody><tr v-for="b in bills" class="border-b"><td class="p-2 font-bold">{{b.bill_number}}</td><td>{{b.accounting_suppliers?.name}}</td><td>{{b.supplier_invoice_number||'—'}}</td><td>{{b.status}}</td><td class="text-right">{{money(b.total)}}</td><td class="text-right font-bold">{{money(Number(b.total)-Number(b.paid_amount))}}</td><td class="text-right"><button v-if="b.status!=='paid'" class="secondary" @click="pay(b)">Pay</button></td></tr></tbody></table></div></section><div v-if="receiving" class="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" @click.self="receiving=null"><div class="w-full max-w-3xl rounded-2xl bg-white p-6 shadow-2xl"><div class="flex items-start justify-between gap-3"><div><h2 class="text-xl font-black">Receive Stock — {{receiving.po_number}}</h2><p class="text-sm text-slate-500">{{receiving.accounting_suppliers?.name}}</p></div><button class="secondary" @click="receiving=null">Close</button></div><div class="mt-4 grid gap-3 md:grid-cols-2"><input v-model="receipt.received_date" type="date" class="input"><input v-model="receipt.supplier_reference" class="input" placeholder="Delivery docket / supplier reference"></div><div class="mt-4 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">Product</th><th>Ordered</th><th>Received</th><th>Remaining</th><th class="w-28">Receive now</th></tr></thead><tbody><tr v-for="l in receiving.accounting_purchase_order_lines" :key="l.id" class="border-b"><td class="p-2"><b>{{l.description}}</b><div class="text-xs text-slate-500">{{l.sku||''}}</div></td><td>{{l.quantity}}</td><td>{{l.received_quantity||0}}</td><td>{{l.remaining_quantity||0}}</td><td><input v-if="l.product_id && Number(l.remaining_quantity)>0" v-model.number="receiptQty[l.id]" type="number" min="0" :max="l.remaining_quantity" step="1" class="input"><span v-else class="text-xs text-slate-400">{{l.product_id?'Complete':'Non-stock'}}</span></td></tr></tbody></table></div><textarea v-model="receipt.notes" class="input mt-3" rows="2" placeholder="Receiving notes (optional)"></textarea><div class="mt-4 flex justify-end"><button class="primary" @click="receiveStock">Receive Stock</button></div></div></div></main></template>

<script setup lang="ts">definePageMeta({layout:"admin",middleware:["admin"]});const{adminFetch}=useAdminFetch();const suppliers=ref<any[]>([]),products=ref<any[]>([]),mappings=ref<any[]>([]),supplierProducts=ref<any[]>([]),selectedMapping=ref(0),pos=ref<any[]>([]),bills=ref<any[]>([]),msg=ref("");const editingPoId=ref<number|null>(null),editingPoNumber=ref("");const receiving=ref<any>(null),receiptQty=reactive<Record<number,number>>({}),receipt=reactive<any>({received_date:new Date().toISOString().slice(0,10),supplier_reference:"",notes:""});const line=()=>({product_id:null,description:"",sku:"",quantity:1,unit_cost_ex_gst:0});const supplier=reactive<any>({name:"",contact_name:"",email:"",phone:"",abn:""});const mapping=reactive<any>({product_id:0,supplier_id:0,supplier_sku:"",supplier_product_name:"",buy_price_ex_gst:"",is_primary:false});const po=reactive<any>({supplier_id:0,expected_date:"",supplier_reference:"",lines:[]});const money=(v:any)=>new Intl.NumberFormat("en-AU",{style:"currency",currency:"AUD"}).format(Number(v||0));const poSubtotal=computed(()=>po.lines.reduce((s:number,l:any)=>s+Number(l.quantity||0)*Number(l.unit_cost_ex_gst||0),0));const supplierName=(id:number)=>suppliers.value.find(x=>x.id===id)?.name||"supplier";async function load(){msg.value="";const results=await Promise.allSettled([adminFetch("/api/admin/accounting/suppliers"),adminFetch("/api/admin/accounting/store-products"),adminFetch("/api/admin/accounting/product-suppliers"),adminFetch("/api/admin/accounting/purchase-orders"),adminFetch("/api/admin/accounting/supplier-bills")]);const targets=[suppliers,products,mappings,pos,bills];results.forEach((r:any,i)=>{if(r.status==="fulfilled")targets[i].value=r.value||[];else console.error("ACCOUNTING PURCHASE LOAD ERROR",r.reason)});if(results.some((r:any)=>r.status==="rejected"))msg.value="Some purchasing data could not be loaded. Check the server log for details."}async function addSupplier(){try{await adminFetch("/api/admin/accounting/suppliers",{method:"POST",body:supplier});Object.assign(supplier,{name:"",contact_name:"",email:"",phone:"",abn:""});await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}async function assignSupplier(){try{await adminFetch("/api/admin/accounting/product-suppliers",{method:"POST",body:mapping});msg.value="Product supplier saved.";Object.assign(mapping,{product_id:0,supplier_id:0,supplier_sku:"",supplier_product_name:"",buy_price_ex_gst:"",is_primary:false});await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}async function supplierChanged(){selectedMapping.value=0;po.lines=[];supplierProducts.value=po.supplier_id?await adminFetch("/api/admin/accounting/products-for-supplier",{query:{supplier_id:po.supplier_id}}):[]}function addMappedProduct(){const m=supplierProducts.value.find(x=>x.id===selectedMapping.value);if(!m)return;const x=m.product;po.lines.push({product_id:x.id,description:m.supplier_product_name||x.name,sku:m.supplier_sku||x.product_code||"",quantity:1,unit_cost_ex_gst:Number(m.buy_price_ex_gst??x.buy_price_ex_gst??0)});selectedMapping.value=0}function resetPO(){editingPoId.value=null;editingPoNumber.value="";Object.assign(po,{supplier_id:0,expected_date:"",supplier_reference:"",lines:[]});supplierProducts.value=[];selectedMapping.value=0}
function isDraft(x:any){return String(x?.status||"").toLowerCase()==="draft"}
async function editPO(x:any){if(!isDraft(x))return;editingPoId.value=Number(x.id);editingPoNumber.value=x.po_number||`PO ${x.id}`;Object.assign(po,{supplier_id:Number(x.supplier_id),expected_date:x.expected_date||"",supplier_reference:x.supplier_reference||"",lines:(x.accounting_purchase_order_lines||[]).map((l:any)=>({id:l.id,product_id:l.product_id,description:l.description||"",sku:l.sku||"",quantity:Number(l.quantity||1),unit_cost_ex_gst:Number(l.unit_cost_ex_gst||0)}))});await supplierChangedForEdit();window.scrollTo({top:0,behavior:"smooth"})}
async function supplierChangedForEdit(){selectedMapping.value=0;supplierProducts.value=po.supplier_id?await adminFetch("/api/admin/accounting/products-for-supplier",{query:{supplier_id:po.supplier_id}}):[]}
function cancelEdit(){resetPO()}
async function savePO(){try{if(editingPoId.value){const x:any=await adminFetch(`/api/admin/accounting/purchase-orders/${editingPoId.value}`,{method:"PUT",body:po});msg.value=`${x.po_number||editingPoNumber.value} updated.`}else{const x:any=await adminFetch("/api/admin/accounting/purchase-orders",{method:"POST",body:po});msg.value=`${x.po_number} created.`}resetPO();await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}
async function sendPO(x:any){if(!isDraft(x))return;if(!confirm(`Send ${x.po_number} to the supplier?\n\nOnce sent, this purchase order will be locked from normal editing.`))return;try{await adminFetch(`/api/admin/accounting/purchase-orders/${x.id}/send`,{method:"POST"});msg.value=`${x.po_number} marked as sent to supplier.`;if(editingPoId.value===Number(x.id))resetPO();await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}
function canReceive(x:any){return ["sent","ordered","part_received"].includes(String(x?.status||"").toLowerCase())}
function canBill(x:any){return !["draft","closed","billed"].includes(String(x?.status||"").toLowerCase())}
async function markOrdered(x:any){if(!isDraft(x))return;if(!confirm(`Mark ${x.po_number} as ordered without emailing the supplier?\n\nThe purchase order will be locked from editing and will become available for stock receiving.`))return;try{await adminFetch(`/api/admin/accounting/purchase-orders/${x.id}/mark-ordered`,{method:"POST"});msg.value=`${x.po_number} marked as ordered. No email was sent.`;if(editingPoId.value===Number(x.id))resetPO();await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}
async function closePO(x:any){if(!isDraft(x))return;if(!confirm(`Close ${x.po_number}?\n\nNo email will be sent. The purchase order will be locked and will not be available for stock receiving or billing.`))return;try{await adminFetch(`/api/admin/accounting/purchase-orders/${x.id}/close`,{method:"POST"});msg.value=`${x.po_number} closed. No email was sent.`;if(editingPoId.value===Number(x.id))resetPO();await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}async function convertToBill(x:any){const inv=prompt("Supplier invoice number",x.supplier_reference||"");if(inv===null)return;const due=prompt("Due date (YYYY-MM-DD)","")||null;try{const b:any=await adminFetch(`/api/admin/accounting/purchase-orders/${x.id}/bill`,{method:"POST",body:{supplier_invoice_number:inv,due_date:due}});msg.value=`${b.bill_number} created and posted to Accounts Payable.`;await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}async function pay(b:any){const owing=Number(b.total)-Number(b.paid_amount),raw=prompt(`Payment amount for ${b.bill_number}`,owing.toFixed(2));if(raw===null)return;const ref=prompt("Payment reference","")||"";try{await adminFetch("/api/admin/accounting/supplier-payments",{method:"POST",body:{bill_id:b.id,amount:Number(raw),reference:ref}});msg.value="Supplier payment posted.";await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}const hasReceivable=(x:any)=>(x.accounting_purchase_order_lines||[]).some((l:any)=>l.product_id&&Number(l.remaining_quantity||0)>0);function openReceive(x:any){receiving.value=x;for(const k of Object.keys(receiptQty))delete receiptQty[Number(k)];for(const l of x.accounting_purchase_order_lines||[])if(l.product_id&&Number(l.remaining_quantity)>0)receiptQty[l.id]=Number(l.remaining_quantity);receipt.received_date=new Date().toISOString().slice(0,10);receipt.supplier_reference=x.supplier_reference||"";receipt.notes=""}async function receiveStock(){if(!receiving.value)return;try{await adminFetch(`/api/admin/accounting/purchase-orders/${receiving.value.id}/receive`,{method:"POST",body:{...receipt,lines:(receiving.value.accounting_purchase_order_lines||[]).map((l:any)=>({purchase_order_line_id:l.id,quantity:Number(receiptQty[l.id]||0)}))}});msg.value="Stock received and inventory updated.";receiving.value=null;await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}onMounted(load)</script>
<style scoped>.panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.input{@apply w-full rounded-lg border border-slate-300 px-3 py-2 text-sm}.primary{@apply rounded-lg bg-blue-600 px-4 py-2 text-sm font-bold text-white}.secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-bold}.badge{@apply ml-2 rounded-full bg-blue-100 px-2 py-0.5 text-[10px] font-black uppercase text-blue-700}</style>